using System;
using System.IO;
using System.Text.RegularExpressions;
using NUnit.Framework;
using UnityEngine;

namespace DeliveryLab.Tests
{
    public sealed class InventoryTests
    {
        string scratch,allowed;
        [SetUp] public void Setup() { allowed=Path.GetFullPath(Path.Combine(Application.dataPath,"../../Evidence/TestScratch")); scratch=Path.Combine(allowed,Guid.NewGuid().ToString("N")); Directory.CreateDirectory(scratch); }
        [TearDown] public void Cleanup() { string resolved=Path.GetFullPath(scratch); if(!resolved.StartsWith(allowed+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)) throw new Exception("Unsafe test path"); if(Directory.Exists(resolved)) Directory.Delete(resolved,true); }
        static string Json(Inventory m)=>JsonUtility.ToJson(m.Snapshot);
        [TestCase(10,2)] [TestCase(20,1)] public void ConfigurableStackCapChangesDistribution(int cap,int expected) { var m=new Inventory(cap); Assert.IsTrue(m.Add("shard",11,out _)); int filled=0,total=0; foreach(var s in m.Snapshot.slots) {if(s.quantity>0)filled++;total+=s.quantity;Assert.LessOrEqual(s.quantity,cap);} Assert.AreEqual(expected,filled);Assert.AreEqual(11,total); }
        [TestCase(-1)] [TestCase(0)] public void NonpositiveAddCannotMutateState(int qty) {var m=new Inventory(10);string before=Json(m);Assert.IsFalse(m.Add("tonic",qty,out _));Assert.AreEqual(before,Json(m));}
        [Test] public void FullInventoryRejectsAtomically() {var m=new Inventory(10);Assert.IsTrue(m.Add("shard",120,out _));string before=Json(m);Assert.IsFalse(m.Add("key",1,out _));Assert.AreEqual(before,Json(m));}
        [Test] public void InvalidItemCannotEnterInventory() {var m=new Inventory(10);Assert.IsFalse(m.Add("unlicensed-mystery",2,out _));Assert.AreEqual("",m.Snapshot.slots[0].item);}
        [Test] public void InvalidSelectionKeepsState() {var m=new Inventory(10);Assert.IsFalse(m.Select(12));Assert.IsFalse(m.Select(-1));Assert.AreEqual(-1,m.Snapshot.selectedSlot);}
        [Test] public void TonicAtFullHealthIsKept() {var m=new Inventory(10);m.Add("tonic",4,out _);Assert.IsTrue(m.Use(0,out _));Assert.AreEqual(84,m.Snapshot.health);m.Use(0,out _);Assert.AreEqual(100,m.Snapshot.health);string before=Json(m);Assert.IsFalse(m.Use(0,out _));Assert.AreEqual(before,Json(m));}
        [TestCase("shard",5)] [TestCase("key",10)] [TestCase("chip",20)] public void UseTradesExactlyOneItem(string id,int reward) {var m=new Inventory(10);m.Add(id,1,out _);Assert.IsTrue(m.Use(0,out _));Assert.AreEqual(125+reward,m.Snapshot.coins);Assert.AreEqual(0,m.Snapshot.slots[0].quantity);Assert.AreEqual("",m.Snapshot.slots[0].item);}
        [TestCase(-1)] [TestCase(0)] [TestCase(5)] public void InvalidRemovalDoesNotChangeState(int qty) {var m=new Inventory(10);m.Add("key",2,out _);string before=Json(m);Assert.IsFalse(m.Remove(0,qty,out _));Assert.AreEqual(before,Json(m));}
        [Test] public void UnknownSchemaCannotReplaceRunningState() {var m=new Inventory(10);m.Add("key",2,out _);string before=Json(m);var candidate=m.Snapshot;candidate.schemaVersion=999;Assert.IsFalse(m.Restore(candidate,out _));Assert.AreEqual(before,Json(m));}
        [Test] public void NegativeSaveQuantityRejected() {var m=new Inventory(10);var s=m.Snapshot;s.slots[0].item="tonic";s.slots[0].quantity=-2;Assert.IsFalse(m.Restore(s,out _));}
        [Test] public void SnapshotAndRestoreHaveNoMutableAliasing() {var m=new Inventory(10);m.Add("key",2,out _);var s=m.Snapshot;s.slots[0].quantity=3;Assert.AreEqual(2,m.Snapshot.slots[0].quantity);m.Restore(s,out _);s.slots[0].quantity=9;Assert.AreEqual(3,m.Snapshot.slots[0].quantity);}
        [Test] public void MaximumRevisionStillAllowsMutationAndPersistence() {var m=new Inventory(20);m.Add("tonic",2,out _);var imported=m.Snapshot;imported.revision=int.MaxValue;Assert.IsTrue(m.Restore(imported,out _));Assert.IsTrue(m.Select(0));Assert.IsTrue(m.Add("shard",1,out _));Assert.IsTrue(m.Use(0,out _));Assert.IsTrue(m.Remove(1,1,out _));Assert.AreEqual(84,m.Snapshot.health);Assert.AreEqual(1,m.Snapshot.slots[0].quantity);Assert.AreEqual(int.MaxValue,m.Snapshot.revision);Assert.IsTrue(Inventory.Validate(m.Snapshot,20,out _));var store=new SaveStore(scratch,20);Assert.IsTrue(store.Save(m.Snapshot,out _));Assert.IsTrue(store.Load(false,out var roundTrip,out _));Assert.AreEqual(Json(m),JsonUtility.ToJson(roundTrip));}
        [Test] public void BaselineSaveLoadsAfterStackCapIncrease() {var baseline=new Inventory(10);baseline.Add("shard",11,out _);var changed=new Inventory(20);Assert.IsTrue(changed.Restore(baseline.Snapshot,out _));Assert.AreEqual(20,changed.Snapshot.stackLimit);Assert.AreEqual(10,changed.Snapshot.slots[0].quantity);Assert.AreEqual(1,changed.Snapshot.slots[1].quantity);}
        [Test] public void VersionedSaveRoundTripsCompleteState() {var m=new Inventory(10);m.Add("shard",4,out _);m.Select(0);m.Use(0,out _);var store=new SaveStore(scratch,10);Assert.IsTrue(store.Save(m.Snapshot,out _));Assert.IsTrue(store.Load(false,out var saved,out _));var restored=new Inventory(10);Assert.IsTrue(restored.Restore(saved,out _));Assert.AreEqual(Json(m),Json(restored));Assert.IsFalse(File.Exists(store.PrimaryPath+".tmp"));}
        [Test] public void SecondCommitPreservesFirstAsBackup() {var m=new Inventory(10);m.Add("key",2,out _);var store=new SaveStore(scratch,10);store.Save(m.Snapshot,out _);string first=Json(m);m.Use(0,out _);store.Save(m.Snapshot,out _);Assert.IsTrue(store.Load(true,out var backup,out _));Assert.AreEqual(first,JsonUtility.ToJson(backup));}
        [Test] public void CorruptFileCannotDestroyRunningState() {var m=new Inventory(10);m.Add("key",2,out _);var store=new SaveStore(scratch,10);store.Save(m.Snapshot,out _);File.WriteAllText(store.PrimaryPath,"{ broken");string before=Json(m);if(store.Load(false,out var candidate,out _))m.Restore(candidate,out _);Assert.AreEqual(before,Json(m));Assert.IsNull(candidate);}
        [TestCase("coins")] [TestCase("health")] [TestCase("schemaVersion")] [TestCase("stackLimit")] [TestCase("revision")] [TestCase("selectedSlot")] public void MissingRequiredJsonFieldCannotSilentlyResetData(string field) {var m=new Inventory(20);m.Add("shard",3,out _);m.Use(0,out _);var store=new SaveStore(scratch,20);store.Save(m.Snapshot,out _);string json=File.ReadAllText(store.PrimaryPath);json=Regex.Replace(json,"\""+field+"\"\\s*:\\s*-?\\d+\\s*,?","");File.WriteAllText(store.PrimaryPath,json);Assert.IsFalse(store.Load(false,out _,out _),"Missing required field accepted: "+field);}
        [TestCase("1.5")] [TestCase("2147483648")] public void NonIntegralOrOverflowJsonCounterRejected(string value) {var m=new Inventory(20);var store=new SaveStore(scratch,20);store.Save(m.Snapshot,out _);string json=Regex.Replace(File.ReadAllText(store.PrimaryPath),"\"coins\"\\s*:\\s*\\d+","\"coins\": "+value);File.WriteAllText(store.PrimaryPath,json);Assert.IsFalse(store.Load(false,out _,out _),"Invalid integer accepted: "+value);}
        [Test] public void LegitimateZeroValuesRemainLoadable() {var m=new Inventory(20);var s=m.Snapshot;s.coins=0;s.health=0;s.revision=0;s.selectedSlot=0;var store=new SaveStore(scratch,20);Assert.IsTrue(store.Save(s,out _));Assert.IsTrue(store.Load(false,out var loaded,out _));Assert.AreEqual(JsonUtility.ToJson(s),JsonUtility.ToJson(loaded));}
        [TestCase("item")] [TestCase("quantity")] public void MissingSlotFieldRejectedThroughLoad(string field) {var store=new SaveStore(scratch,20);store.Save(new Inventory(20).Snapshot,out _);string json=File.ReadAllText(store.PrimaryPath);var regex=new Regex(field=="item"?"\"item\"\\s*:\\s*\"\"\\s*,":"\"quantity\"\\s*:\\s*0");json=regex.Replace(json,"",1);File.WriteAllText(store.PrimaryPath,json);Assert.IsFalse(store.Load(false,out _,out _));}
        [Test] public void DuplicateIntegerFieldRejected() {var store=new SaveStore(scratch,20);store.Save(new Inventory(20).Snapshot,out _);string json=File.ReadAllText(store.PrimaryPath).Replace("\"coins\": 125","\"coins\": 1, \"coins\": 125");File.WriteAllText(store.PrimaryPath,json);Assert.IsFalse(store.Load(false,out _,out _));}
        [Test] public void EscapedDuplicateCounterCannotBypassPreflight() {var store=new SaveStore(scratch,20);store.Save(new Inventory(20).Snapshot,out _);string json=File.ReadAllText(store.PrimaryPath).Replace("\"coins\": 125","\"coins\":125,\"\\u0063oins\":1.5");File.WriteAllText(store.PrimaryPath,json);Assert.IsFalse(store.Load(false,out _,out _));}
        [Test] public void DuplicateItemPropertyRejected() {var store=new SaveStore(scratch,20);store.Save(new Inventory(20).Snapshot,out _);string json=File.ReadAllText(store.PrimaryPath).Replace("\"item\": \"\"","\"item\":\"\",\"item\":\"\"");File.WriteAllText(store.PrimaryPath,json);Assert.IsFalse(store.Load(false,out _,out _));}
        [Test] public void MissingSaveIsHandledWithoutCandidate() {var store=new SaveStore(scratch,10);Assert.IsFalse(store.Load(false,out var candidate,out _));Assert.IsNull(candidate);}
        [Test] public void OversizedSaveRejectedBeforeParsing() {var store=new SaveStore(scratch,10);File.WriteAllText(store.PrimaryPath,new string('x',1024*1024+1));Assert.IsFalse(store.Load(false,out _,out var error));StringAssert.Contains("oversized",error);}
        [Test] public void SavingAfterCorruptionKeepsLastValidBackup() {var m=new Inventory(10);m.Add("key",2,out _);var store=new SaveStore(scratch,10);store.Save(m.Snapshot,out _);string first=Json(m);m.Use(0,out _);store.Save(m.Snapshot,out _);File.WriteAllText(store.PrimaryPath,"broken");Assert.IsTrue(store.Save(m.Snapshot,out _));Assert.IsTrue(store.Load(true,out var backup,out _));Assert.AreEqual(first,JsonUtility.ToJson(backup));}
        [Test] public void FailedReplacePreservesCommittedFile() {var m=new Inventory(10);var store=new SaveStore(scratch,10);store.Save(m.Snapshot,out _);string before=File.ReadAllText(store.PrimaryPath);m.Add("key",1,out _);using(var held=new FileStream(store.PrimaryPath,FileMode.Open,FileAccess.Read,FileShare.None))Assert.IsFalse(store.Save(m.Snapshot,out _));Assert.AreEqual(before,File.ReadAllText(store.PrimaryPath));Assert.IsFalse(File.Exists(store.PrimaryPath+".tmp"));}
    }
}
